static int[] bfs(List<List<Integer>> adj, int start) {
    int[] dist = new int[adj.size()];
    Arrays.fill(dist, -1);
    Queue<Integer> queue = new ArrayDeque<>();
    dist[start] = 0;
    queue.add(start);
    while (!queue.isEmpty()) {
        int u = queue.remove();
        for (int v : adj.get(u)) {
            if (dist[v] == -1) {
                dist[v] = dist[u] + 1;
                queue.add(v);
            }
        }
    }
    return dist;
}

knapsack-01:
static int knapsack(int[] w, int[] v, int cap) {
    int[][] t = new int[w.length + 1][cap + 1];
    for (int i = 1; i <= w.length; i++) {
        for (int c = 0; c <= cap; c++) {
            t[i][c] = t[i - 1][c];
            if (c >= w[i - 1]) {
                t[i][c] = Math.max(t[i][c], t[i - 1][c - w[i - 1]] + v[i - 1]);
            }
        }
    }
    return t[w.length][cap];
}

lis:
static int lis(int[] a) {
    int[] len = new int[a.length];
    int best = 0;
    for (int i = 0; i < a.length; i++) {
        len[i] = 1;
        for (int j = 0; j < i; j++) {
            if (a[j] < a[i]) len[i] = Math.max(len[i], len[j] + 1);
        }
        best = Math.max(best, len[i]);
    }
    return best;
}

