static boolean place(int[] col, int row, int n) {
    if (row == n) return true;
    for (int c = 0; c < n; c++) {
        if (safe(col, row, c)) {
            col[row] = c;
            if (place(col, row + 1, n)) return true;
        }
    }
    return false;
}

