class ArrayStack {
    private int[] data = new int[8];
    private int size = 0;

    void push(int x) {
        if (size == data.length) data = Arrays.copyOf(data, size * 2);
        data[size++] = x;
    }

    int pop() {
        return data[--size];
    }
}

